import{_ as t}from"./chunks/eye.BRl0ZGNz.js";import{_ as a,c as s,o as l,ag as o}from"./chunks/framework.DZ_cNctr.js";const g=JSON.parse('{"title":"Example: a Plate with Analysis Results","description":"Open BBBC013, a 96-well screen, together with its segmentation masks and 18,648 measured nuclei. One click in the Example Gallery, nothing to install or upload.","frontmatter":{"title":"Example: a Plate with Analysis Results","description":"Open BBBC013, a 96-well screen, together with its segmentation masks and 18,648 measured nuclei. One click in the Example Gallery, nothing to install or upload."},"headers":[],"relativePath":"guides/example-plate-results.md","filePath":"guides/example-plate-results.md"}'),r={name:"guides/example-plate-results.md"};function n(i,e,h,c,p,m){return l(),s("div",null,[...e[0]||(e[0]=[o('<h1 id="example-a-plate-with-analysis-results" tabindex="-1">Example: a Plate with Analysis Results <a class="header-anchor" href="#example-a-plate-with-analysis-results" aria-label="Permalink to &quot;Example: a Plate with Analysis Results&quot;">​</a></h1><p>Most examples show pixels. This one shows what an analysis adds on top: masks for every nucleus and cell, and a measurement table behind each of them. It opens in one click, straight from our site.</p><p><strong><a href="https://find-nuclei.github.io/?url=https%3A%2F%2Ffind-nuclei.github.io%2Fexamples%2Fbbbc013%2FBBBC013.zarr&amp;analyticsUrl=https%3A%2F%2Ffind-nuclei.github.io%2Fexamples%2Fbbbc013%2FBBBC013.zarr.analytics%2F0b1e47a7-stardist-cellpose%2F&amp;tab=labels&amp;c=0%3Aon%3A808080%3A3%3A134%3A1.00%2C1%3Aon%3AFFFFFF%3A1%3A100%3A1.00&amp;v=plate&amp;w=A%2F1&amp;f=0&amp;zm=0.77&amp;xy=4446%2C2322&amp;cm=C&amp;inv=t&amp;bg=%23ffffff&amp;l=ext%3Acells%2Cext%3Anuclei&amp;lv=cells%3Acategory%3Aphenotype_class&amp;ls=cells%3A0.5%3Afc%2Cnuclei%3A0.5%3Afc%3A808080" target="_blank" rel="noreferrer">Open the example in the viewer</a></strong></p><p>Or open the <strong>Example Gallery</strong> and pick <strong>BBBC013 FKHR translocation</strong>. The <strong>Results</strong> filter shows only examples that come with results.</p><h2 id="what-is-in-it" tabindex="-1">What is in it <a class="header-anchor" href="#what-is-in-it" aria-label="Permalink to &quot;What is in it&quot;">​</a></h2><p><strong>The plate.</strong> BBBC013 from the Broad Bioimage Benchmark Collection. Human U2OS cells express FKHR-GFP, a protein that moves from the cytoplasm into the nucleus when the PI3K pathway is blocked. Two inhibitors run as dose series across the plate: Wortmannin in rows A to D, LY294002 in rows E to H. Two channels: DRAQ for DNA, and FKHR-GFP.</p><p><strong>The results.</strong> One analysis run, three compartments:</p><table tabindex="0"><thead><tr><th>Mask</th><th>Objects</th><th>Made with</th></tr></thead><tbody><tr><td>nuclei</td><td>18,648</td><td>StarDist (<code>2D_versatile_fluo</code>)</td></tr><tr><td>cells</td><td>15,331</td><td>Cellpose (<code>cyto3</code>)</td></tr><tr><td>cytoplasm</td><td>15,272</td><td>each cell minus its nucleus</td></tr></tbody></table><p>Each mask carries its own table: area, shape and intensity for every object, plus well and plate summaries.</p><h2 id="look-around" tabindex="-1">Look around <a class="header-anchor" href="#look-around" aria-label="Permalink to &quot;Look around&quot;">​</a></h2><ol><li>The whole plate opens inverted on white. Cells are coloured by the phenotype the analysis gave them: <strong>positive</strong>, <strong>negative</strong> or <strong>excluded</strong>. Nuclei are drawn in grey on top.</li><li>The <strong>Labels</strong> tab lists the three masks under one heading, the analysis run. Press the <img src="'+t+'" class="fn-icon" alt="visibility"> on a mask to show or hide it.</li><li>Click the <strong>nuclei</strong> row to open its details. The <strong>Analytics</strong> section lists the measured columns.</li><li>Colour the nuclei by a column, filter them by value, or build a phenotype. See <a href="./analytics-phenotyping.html">Analytics &amp; Phenotyping</a>.</li><li>Zoom into a well, or pick one from the <strong>Navigation</strong> tab. See <a href="./hcs-plates.html">HCS Plates</a>.</li></ol><p>A good first column: colour the nuclei by <code>ch1_mean</code>, the mean FKHR-GFP inside each nucleus. In wells with more inhibitor, more of the signal sits in the nucleus.</p><h2 id="who-made-the-masks" tabindex="-1">Who made the masks <a class="header-anchor" href="#who-made-the-masks" aria-label="Permalink to &quot;Who made the masks&quot;">​</a></h2><p>We ran the Find Nuclei Analysis Tool over the plate. The masks and measurements are our output, not part of the original collection.</p><div class="warning custom-block"><p class="custom-block-title">Cellpose is research only</p><p>The cell masks come from Cellpose. Our licence review lists its pretrained models as research only, so we show them here as a viewing example. The nuclei come from StarDist&#39;s fluorescence model, which our review rates safe for commercial use.</p></div><h2 id="use-your-own-results" tabindex="-1">Use your own results <a class="header-anchor" href="#use-your-own-results" aria-label="Permalink to &quot;Use your own results&quot;">​</a></h2><p>Everything here is plain files on a web server: an OME-Zarr plate, and next to it a folder with masks, Parquet tables and a manifest. Put yours on any host that answers the browser directly, and the same link pattern opens them:</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>?url=&lt;plate&gt;&amp;analyticsUrl=&lt;run-folder&gt;/</span></span></code></pre></div><p>The <a href="./analytics-format.html">Analytics Data Format</a> describes the files, from a single CSV up to a full run. <a href="./sharing.html">Sharing Views</a> covers what else a link can carry.</p><p>For a walkthrough of the analysis itself on this same screen, read <a href="https://www.find-nuclei.com/blog/hcs-analytics-in-the-browser" target="_blank" rel="noreferrer">HCS Analytics in the Browser: 18,648 Nuclei, Zero Uploads</a>.</p><h2 id="image-credits" tabindex="-1">Image credits <a class="header-anchor" href="#image-credits" aria-label="Permalink to &quot;Image credits&quot;">​</a></h2><p>Images: <a href="https://bbbc.broadinstitute.org/BBBC013" target="_blank" rel="noreferrer">BBBC013v1</a>, provided by Ilya Ravkin, available from the Broad Bioimage Benchmark Collection, under <a href="https://creativecommons.org/licenses/by/3.0/" target="_blank" rel="noreferrer">CC BY 3.0</a>.</p><blockquote><p>Ljosa V, Sokolnicki KL, Carpenter AE (2012). Annotated high-throughput microscopy image sets for validation. <em>Nature Methods</em> 9(7):637. <a href="https://doi.org/10.1038/nmeth.2083" target="_blank" rel="noreferrer">doi:10.1038/nmeth.2083</a></p></blockquote><p>See <a href="./../sample-data.html">Sample Data and Credits</a> for every dataset used in these guides.</p>',24)])])}const f=a(r,[["render",n]]);export{g as __pageData,f as default};
